### 2. 数学工具 (math-utils.js)

```javascript
// src/common/utils/math-utils.js

export function kalmanFilter(data, windowSize = 5) {
  if (data.length < windowSize) {
    return data;
  }

  const result = [];
  for (let i = 0; i < data.length; i++) {
    const start = Math.max(0, i - Math.floor(windowSize / 2));
    const end = Math.min(data.length, i + Math.floor(windowSize / 2) + 1);
    const window = data.slice(start, end);
    const avg = window.reduce((sum, val) => sum + val, 0) / window.length;
    result.push(avg);
  }

  return result;
}

export function lowPassFilter(current, previous, alpha = 0.8) {
  return alpha * previous + (1 - alpha) * current;
}

export function calculateAngle(acceleration, gravity = 9.81) {
  const { x, y, z } = acceleration;
  const magnitude = Math.sqrt(x * x + y * y + z * z);

  if (magnitude === 0) return 0;

  const sinAngle = Math.sqrt(x * x + z * z) / magnitude;
  const angle = Math.asin(sinAngle) * (180 / Math.PI);

  return Math.round(angle * 10) / 10;
}

export function weightedAverage(values, weights) {
  if (values.length !== weights.length) {
    throw new Error('Values and weights must have same length');
  }

  let sum = 0;
  let weightSum = 0;

  for (let i = 0; i < values.length; i++) {
    sum += values[i] * weights[i];
    weightSum += weights[i];
  }

  return weightSum === 0 ? 0 : sum / weightSum;
}

export function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

export function linearInterpolation(start, end, factor) {
  return start + (end - start) * factor;
}
```

### 3. 姿态评估引擎 (posture-engine.js)

```javascript
// src/common/lib/posture-engine.js

import { POSTURE_GRADES, POSTURE_THRESHOLDS } from '../utils/constants';
import { calculateAngle, weightedAverage, clamp } from '../utils/math-utils';

export default class PostureEngine {
  constructor() {
    this.weights = {
      head: 0.3,
      neck: 0.4,
      back: 0.3
    };

    this.history = [];
    this.maxHistorySize = 100;
  }

  /**
   * 评估姿态
   * @param {Object} sensorData - 传感器数据
   * @returns {Object} 评估结果
   */
  assess(sensorData) {
    const { acceleration, gyroscope } = sensorData;

    // 计算各部位角度
    const headAngle = this.calculateHeadAngle(acceleration);
    const neckAngle = this.calculateNeckAngle(acceleration, gyroscope);
    const backAngle = this.calculateBackAngle(acceleration);

    // 计算综合评分
    const score = this.calculateOverallScore(headAngle, neckAngle, backAngle);

    // 判定等级
    const grade = this.determineGrade(score);

    // 计算偏离度
    const deviation = this.calculateDeviation(headAngle, neckAngle, backAngle);

    const result = {
      headAngle,
      neckAngle,
      backAngle,
      score,
      grade,
      deviation,
      timestamp: Date.now()
    };

    // 记录历史
    this.addToHistory(result);

    return result;
  }

  /**
   * 计算头部角度
   */
  calculateHeadAngle(acceleration) {
    const angle = calculateAngle(acceleration);
    return clamp(angle, 0, 90);
  }

  /**
   * 计算颈部角度
   */
  calculateNeckAngle(acceleration, gyroscope) {
    const { x, y, z } = acceleration;

    // 基于加速度计的颈部角度
    const accelAngle = Math.atan2(x, Math.sqrt(y * y + z * z)) * (180 / Math.PI);

    // 基于陀螺仪的角速度积分（简化）
    const gyroAngle = gyroscope ? gyroscope.x * 0.1 : 0;

    // 融合算法
    const fusedAngle = 0.8 * accelAngle + 0.2 * gyroAngle;

    return clamp(Math.abs(fusedAngle), 0, 90);
  }

  /**
   * 计算背部角度
   */
  calculateBackAngle(acceleration) {
    const { y, z } = acceleration;
    const angle = Math.atan2(y, z) * (180 / Math.PI);

    return clamp(Math.abs(angle), 0, 90);
  }

  /**
   * 计算综合评分
   */
  calculateOverallScore(headAngle, neckAngle, backAngle) {
    // 各部位评分（0-100分）
    const headScore = this.scoreAngle(headAngle, POSTURE_THRESHOLDS.HEAD_ANGLE);
    const neckScore = this.scoreAngle(neckAngle, POSTURE_THRESHOLDS.NECK_ANGLE);
    const backScore = this.scoreAngle(backAngle, POSTURE_THRESHOLDS.BACK_ANGLE);

    // 加权平均
    const scores = [headScore, neckScore, backScore];
    const weights = [this.weights.head, this.weights.neck, this.weights.back];

    return Math.round(weightedAverage(scores, weights));
  }

  /**
   * 角度评分
   */
  scoreAngle(angle, thresholds) {
    if (angle <= thresholds.GOOD) {
      return 100;
    } else if (angle <= thresholds.FAIR) {
      // 线性插值 60-100
      const factor = (thresholds.FAIR - angle) / (thresholds.FAIR - thresholds.GOOD);
      return 60 + factor * 40;
    } else if (angle <= thresholds.POOR) {
      // 线性插值 30-60
      const factor = (thresholds.POOR - angle) / (thresholds.POOR - thresholds.FAIR);
      return 30 + factor * 30;
    } else {
      // 低于30分
      const factor = Math.max(0, 1 - (angle - thresholds.POOR) / 30);
      return factor * 30;
    }
  }

  /**
   * 判定等级
   */
  determineGrade(score) {
    if (score >= 80) return POSTURE_GRADES.GOOD;
    if (score >= 60) return POSTURE_GRADES.FAIR;
    return POSTURE_GRADES.POOR;
  }

  /**
   * 计算偏离度
   */
  calculateDeviation(headAngle, neckAngle, backAngle) {
    const headDev = Math.max(0, headAngle - POSTURE_THRESHOLDS.HEAD_ANGLE.GOOD);
    const neckDev = Math.max(0, neckAngle - POSTURE_THRESHOLDS.NECK_ANGLE.GOOD);
    const backDev = Math.max(0, backAngle - POSTURE_THRESHOLDS.BACK_ANGLE.GOOD);

    return Math.round((headDev + neckDev + backDev) / 3);
  }

  /**
   * 添加到历史记录
   */
  addToHistory(result) {
    this.history.push(result);

    if (this.history.length > this.maxHistorySize) {
      this.history.shift();
    }
  }

  /**
   * 获取历史统计
   */
  getStatistics() {
    if (this.history.length === 0) {
      return {
        averageScore: 0,
        goodRate: 0,
        poorRate: 0,
        averageDeviation: 0
      };
    }

    const scores = this.history.map(h => h.score);
    const deviations = this.history.map(h => h.deviation);
    const grades = this.history.map(h => h.grade);

    const averageScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const goodCount = grades.filter(g => g === POSTURE_GRADES.GOOD).length;
    const poorCount = grades.filter(g => g === POSTURE_GRADES.POOR).length;
    const averageDeviation = Math.round(deviations.reduce((a, b) => a + b, 0) / deviations.length);

    return {
      averageScore,
      goodRate: Math.round((goodCount / grades.length) * 100),
      poorRate: Math.round((poorCount / grades.length) * 100),
      averageDeviation
    };
  }

  /**
   * 重置历史
   */
  resetHistory() {
    this.history = [];
  }
}
```

### 4. 干预决策系统 (intervention-system.js)

```javascript
// src/common/lib/intervention-system.js

import { INTERVENTION_CONFIG, POSTURE_GRADES } from '../utils/constants';

export default class InterventionSystem {
  constructor(config = {}) {
    this.config = {
      sittingDurationThreshold: config.sittingDurationThreshold || INTERVENTION_CONFIG.SITTING_DURATION_THRESHOLD,
      cumulativePoorThreshold: config.cumulativePoorThreshold || INTERVENTION_CONFIG.CUMULATIVE_POOR_THRESHOLD,
      deviationThreshold: config.deviationThreshold || INTERVENTION_CONFIG.DEVIATION_THRESHOLD,
      ...config
    };

    this.session = {
      startTime: null,
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    this.interventionHistory = [];
  }

  /**
   * 开始监测会话
   */
  startSession() {
    this.session = {
      startTime: Date.now(),
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    console.log('[Intervention] 会话开始');
  }

  /**
   * 停止监测会话
   */
  stopSession() {
    const sessionData = { ...this.session };
    this.interventionHistory.push(sessionData);

    console.log('[Intervention] 会话结束', sessionData);

    this.session = {
      startTime: null,
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    return sessionData;
  }

  /**
   * 更新监测数据
   * @param {Object} postureResult - 姿态评估结果
   * @returns {Object} 干预决策
   */
  update(postureResult) {
    if (!this.session.startTime) {
      return { shouldIntervene: false, reason: null };
    }

    // 更新久坐时长
    this.updateSittingDuration();

    // 更新累计不良姿态
    this.updateCumulativePoor(postureResult);

    // 检查是否需要干预
    const intervention = this.checkIntervention(postureResult);

    return intervention;
  }

  /**
   * 更新久坐时长
   */
  updateSittingDuration() {
    if (this.session.startTime) {
      this.session.sittingDuration = Math.floor((Date.now() - this.session.startTime) / 60000);
    }
  }

  /**
   * 更新累计不良姿态
   */
  updateCumulativePoor(postureResult) {
    if (postureResult.grade === POSTURE_GRADES.POOR) {
      this.session.cumulativePoor++;
    } else if (postureResult.grade === POSTURE_GRADES.GOOD) {
      // 良好姿态可以重置计数
      this.session.cumulativePoor = Math.max(0, this.session.cumulativePoor - 1);
    }
  }

  /**
   * 检查是否需要干预
   */
  checkIntervention(postureResult) {
    const reasons = [];

    // 检查久坐时间
    if (this.session.sittingDuration >= this.config.sittingDurationThreshold) {
      reasons.push('sitting_duration');
    }

    // 检查姿态偏离
    if (postureResult.deviation >= this.config.deviationThreshold) {
      reasons.push('posture_deviation');
    }

    // 检查累计不良
    if (this.session.cumulativePoor >= this.config.cumulativePoorThreshold) {
      reasons.push('cumulative_poor');
    }

    // 防止频繁干预（至少间隔5分钟）
    const now = Date.now();
    if (this.session.lastInterventionTime) {
      const timeSinceLastIntervention = now - this.session.lastInterventionTime;
      if (timeSinceLastIntervention < 5 * 60 * 1000) {
        return {
          shouldIntervene: false,
          reason: null,
          message: '距离上次提醒不足5分钟'
        };
      }
    }

    if (reasons.length > 0) {
      this.session.interventionCount++;
      this.session.lastInterventionTime = now;

      const message = this.generateMessage(reasons, postureResult);

      return {
        shouldIntervene: true,
        reason: reasons[0],
        message,
        timestamp: now
      };
    }

    return {
      shouldIntervene: false,
      reason: null
    };
  }

  /**
   * 生成干预消息
   */
  generateMessage(reasons, postureResult) {
    const messages = {
      sitting_duration: '您已经连续坐了' + this.session.sittingDuration + '分钟，建议起身活动一下',
      posture_deviation: '检测到您的坐姿偏离较大，请调整姿势',
      cumulative_poor: '您今天的不良坐姿次数较多，请注意保持正确坐姿'
    };

    const primaryReason = reasons[0];
    let message = messages[primaryReason] || '请注意保持正确坐姿';

    // 根据等级添加额外建议
    if (postureResult.grade === POSTURE_GRADES.POOR) {
      message += '。当前坐姿不佳，请立即调整。';
    } else if (postureResult.grade === POSTURE_GRADES.FAIR) {
      message += '。可以做得更好，继续保持。';
    }

    return message;
  }

  /**
   * 获取会话统计
   */
  getSessionStats() {
    return {
      sittingDuration: this.session.sittingDuration,
      cumulativePoor: this.session.cumulativePoor,
      interventionCount: this.session.interventionCount,
      isMonitoring: !!this.session.startTime
    };
  }

  /**
   * 获取历史统计
   */
  getHistoryStats() {
    if (this.interventionHistory.length === 0) {
      return {
        totalSessions: 0,
        averageInterventions: 0,
        totalInterventions: 0
      };
    }

    const totalInterventions = this.interventionHistory.reduce(
      (sum, session) => sum + session.interventionCount, 0
    );

    return {
      totalSessions: this.interventionHistory.length,
      averageInterventions: Math.round(totalInterventions / this.interventionHistory.length),
      totalInterventions
    };
  }
}
