### 5. 传感器管理 (sensor-manager.js)

```javascript
// src/common/lib/sensor-manager.js

import sensor from '@system.sensor';
import { SENSOR_CONFIG } from '../utils/constants';
import { kalmanFilter, lowPassFilter } from '../utils/math-utils';

export default class SensorManager {
  constructor() {
    this.isRunning = false;
    this.dataBuffer = {
      acceleration: [],
      gyroscope: []
    };

    this.currentData = {
      acceleration: { x: 0, y: 0, z: 0 },
      gyroscope: { x: 0, y: 0, z: 0 }
    };

    this.filteredData = {
      acceleration: { x: 0, y: 0, z: 0 },
      gyroscope: { x: 0, y: 0, z: 0 }
    };

    this callbacks = {
      onData: null,
      onError: null
    };

    this.bufferSize = SENSOR_CONFIG.FILTER_WINDOW;
  }

  /**
   * 注册数据回调
   */
  onData(callback) {
    this.callbacks.onData = callback;
  }

  /**
   * 注册错误回调
   */
  onError(callback) {
    this.callbacks.onError = callback;
  }

  /**
   * 开始采集传感器数据
   */
  start() {
    if (this.isRunning) {
      console.warn('[Sensor] 已经在运行');
      return;
    }

    this.isRunning = true;
    this.dataBuffer = { acceleration: [], gyroscope: [] };

    // 启动加速度计
    this.startAccelerometer();

    // 启动陀螺仪
    this.startGyroscope();

    console.log('[Sensor] 开始采集');
  }

  /**
   * 停止采集
   */
  stop() {
    this.isRunning = false;

    // 停止加速度计
    this.stopAccelerometer();

    // 停止陀螺仪
    this.stopGyroscope();

    console.log('[Sensor] 停止采集');
  }

  /**
   * 启动加速度计
   */
  startAccelerometer() {
    sensor.subscribeAccelerometer({
      callback: (data) => {
        if (!this.isRunning) return;

        this.currentData.acceleration = {
          x: data.x,
          y: data.y,
          z: data.z
        };

        // 更新缓冲区
        this.dataBuffer.acceleration.push(this.currentData.acceleration);
        if (this.dataBuffer.acceleration.length > this.bufferSize) {
          this.dataBuffer.acceleration.shift();
        }

        // 应用滤波
        this.applyFilter();

        // 通知数据更新
        this.notifyDataUpdate();
      }
    });
  }

  /**
   * 停止加速度计
   */
  stopAccelerometer() {
    sensor.unsubscribeAccelerometer();
  }

  /**
   * 启动陀螺仪
   */
  startGyroscope() {
    sensor.subscribeGyroscope({
      callback: (data) => {
        if (!this.isRunning) return;

        this.currentData.gyroscope = {
          x: data.x,
          y: data.y,
          z: data.z
        };

        // 更新缓冲区
        this.dataBuffer.gyroscope.push(this.currentData.gyroscope);
        if (this.dataBuffer.gyroscope.length > this.bufferSize) {
          this.dataBuffer.gyroscope.shift();
        }
      }
    });
  }

  /**
   * 停止陀螺仪
   */
  stopGyroscope() {
    sensor.unsubscribeGyroscope();
  }

  /**
   * 应用滤波
   */
  applyFilter() {
    // 对加速度计数据应用卡尔曼滤波
    if (this.dataBuffer.acceleration.length >= this.bufferSize) {
      const xValues = this.dataBuffer.acceleration.map(d => d.x);
      const yValues = this.dataBuffer.acceleration.map(d => d.y);
      const zValues = this.dataBuffer.acceleration.map(d => d.z);

      const filteredX = kalmanFilter(xValues, this.bufferSize);
      const filteredY = kalmanFilter(yValues, this.bufferSize);
      const filteredZ = kalmanFilter(zValues, this.bufferSize);

      const lastIdx = filteredX.length - 1;

      this.filteredData.acceleration = {
        x: filteredX[lastIdx],
        y: filteredY[lastIdx],
        z: filteredZ[lastIdx]
      };
    } else {
      // 数据不足，使用当前值
      this.filteredData.acceleration = { ...this.currentData.acceleration };
    }

    // 陀螺仪数据使用低通滤波
    if (this.filteredData.gyroscope.x === 0) {
      this.filteredData.gyroscope = { ...this.currentData.gyroscope };
    } else {
      this.filteredData.gyroscope = {
        x: lowPassFilter(this.currentData.gyroscope.x, this.filteredData.gyroscope.x),
        y: lowPassFilter(this.currentData.gyroscope.y, this.filteredData.gyroscope.y),
        z: lowPassFilter(this.currentData.gyroscope.z, this.filteredData.gyroscope.z)
      };
    }
  }

  /**
   * 通知数据更新
   */
  notifyDataUpdate() {
    if (this.callbacks.onData) {
      this.callbacks.onData({
        acceleration: this.filteredData.acceleration,
        gyroscope: this.filteredData.gyroscope,
        raw: this.currentData
      });
    }
  }

  /**
   * 获取当前数据
   */
  getCurrentData() {
    return {
      acceleration: this.filteredData.acceleration,
      gyroscope: this.filteredData.gyroscope
    };
  }
}
