### 6. 存储管理 (storage-manager.js)

```javascript
// src/common/lib/storage-manager.js

import storage from '@system.storage';
import { STORAGE_KEYS } from '../utils/constants';

export default class StorageManager {
  constructor() {
    this.cache = {};
    this.isLoaded = false;
  }

  /**
   * 初始化存储
   */
  async init() {
    try {
      // 加载用户配置
      const config = await this.get(STORAGE_KEYS.USER_CONFIG);
      if (!config) {
        await this.set(STORAGE_KEYS.USER_CONFIG, this.getDefaultConfig());
      }

      this.isLoaded = true;
      console.log('[Storage] 初始化完成');
    } catch (error) {
      console.error('[Storage] 初始化失败:', error);
    }
  }

  /**
   * 获取默认配置
   */
  getDefaultConfig() {
    return {
      alertEnabled: true,
      alertInterval: 30,
      sensitivity: 'medium',
      restDuration: 5,
      dailyGoal: 80,
      workingHours: {
        start: '09:00',
        end: '18:00'
      }
    };
  }

  /**
   * 存储数据
   */
  set(key, value) {
    return new Promise((resolve, reject) => {
      try {
        const data = JSON.stringify(value);
        storage.set({
          key,
          value: data,
          success: () => {
            this.cache[key] = value;
            resolve();
          },
          fail: (error) => {
            reject(error);
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * 获取数据
   */
  get(key) {
    return new Promise((resolve, reject) => {
      // 先检查缓存
      if (this.cache[key] !== undefined) {
        resolve(this.cache[key]);
        return;
      }

      try {
        storage.get({
          key,
          success: (data) => {
            try {
              const value = JSON.parse(data);
              this.cache[key] = value;
              resolve(value);
            } catch (parseError) {
              resolve(data);
            }
          },
          fail: (error) => {
            reject(error);
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * 删除数据
   */
  delete(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key,
        success: () => {
          delete this.cache[key];
          resolve();
        },
        fail: (error) => {
          reject(error);
        }
      });
    });
  }

  /**
   * 存储实时数据
   */
  async saveRealtimeData(data) {
    await this.set(STORAGE_KEYS.REALTIME_DATA, data);
  }

  /**
   * 获取实时数据
   */
  async getRealtimeData() {
    return await this.get(STORAGE_KEYS.REALTIME_DATA);
  }

  /**
   * 保存历史记录
   */
  async saveHistoryRecord(record) {
    const history = await this.get(STORAGE_KEYS.HISTORY_DATA) || [];
    history.push(record);

    // 只保留最近30天的数据
    const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
    const filteredHistory = history.filter(h => h.timestamp > thirtyDaysAgo);

    await this.set(STORAGE_KEYS.HISTORY_DATA, filteredHistory);
  }

  /**
   * 获取历史记录
   */
  async getHistoryRecord() {
    return await this.get(STORAGE_KEYS.HISTORY_DATA) || [];
  }

  /**
   * 保存用户配置
   */
  async saveConfig(config) {
    await this.set(STORAGE_KEYS.USER_CONFIG, config);
  }

  /**
   * 获取用户配置
   */
  async getConfig() {
    return await this.get(STORAGE_KEYS.USER_CONFIG);
  }

  /**
   * 清除历史数据
   */
  async clearHistory() {
    await this.delete(STORAGE_KEYS.HISTORY_DATA);
  }

  /**
   * 清除所有数据
   */
  async clearAll() {
    await this.delete(STORAGE_KEYS.REALTIME_DATA);
    await this.delete(STORAGE_KEYS.HISTORY_DATA);
    await this.delete(STORAGE_KEYS.USER_CONFIG);
    this.cache = {};
  }
}
