import router from '@system.router'
import PostureEngine from '../../common/lib/posture-engine'
import InterventionSystem from '../../common/lib/intervention-system'
import SensorManager from '../../common/lib/sensor-manager'
import StorageManager from '../../common/lib/storage-manager'

export default {
  private: {
    isMonitoring: false,
    currentScore: 85,
    gradeText: '良好',
    headAngle: 15,
    neckAngle: 12,
    backAngle: 18,
    sessionDuration: 0,
    interventionCount: 0,
    showAlert: false,
    alertMessage: '',
    postureEngine: null,
    interventionSystem: null,
    sensorManager: null,
    storageManager: null,
    monitoringTimer: null
  },

  onInit() {
    this.postureEngine = new PostureEngine()
    this.interventionSystem = new InterventionSystem()
    this.sensorManager = new SensorManager()
    this.storageManager = new StorageManager()

    this.sensorManager.onData((data) => {
      this.processSensorData(data)
    })
  },

  onDestroy() {
    this.stopMonitoring()
  },

  toggleMonitoring() {
    if (this.isMonitoring) {
      this.stopMonitoring()
    } else {
      this.startMonitoring()
    }
  },

  startMonitoring() {
    this.isMonitoring = true
    this.interventionSystem.startSession()
    this.sensorManager.start()

    this.monitoringTimer = setInterval(() => {
      this.updateSessionInfo()
    }, 1000)

    this.showAlert = false
    console.log('[Monitor] 开始监测')
  },

  stopMonitoring() {
    this.isMonitoring = false
    this.sensorManager.stop()

    if (this.monitoringTimer) {
      clearInterval(this.monitoringTimer)
      this.monitoringTimer = null
    }

    const sessionData = this.interventionSystem.stopSession()
    this.saveSessionData(sessionData)

    console.log('[Monitor] 停止监测')
  },

  processSensorData(data) {
    const result = this.postureEngine.assess(data)

    this.currentScore = result.score
    this.headAngle = result.headAngle
    this.neckAngle = result.neckAngle
    this.backAngle = result.backAngle
    this.gradeText = this.getGradeText(result.grade)

    const intervention = this.interventionSystem.update(result)
    if (intervention.shouldIntervene) {
      this.showInterventionAlert(intervention.message)
    }
  },

  getGradeText(grade) {
    const gradeMap = {
      good: '良好',
      fair: '一般',
      poor: '不佳'
    }
    return gradeMap[grade] || '未知'
  },

  updateSessionInfo() {
    const stats = this.interventionSystem.getSessionStats()
    this.sessionDuration = stats.sittingDuration
    this.interventionCount = stats.interventionCount
  },

  showInterventionAlert(message) {
    this.alertMessage = message
    this.showAlert = true

    setTimeout(() => {
      this.showAlert = false
    }, 5000)
  },

  async saveSessionData(sessionData) {
    try {
      await this.storageManager.saveHistoryRecord({
        timestamp: Date.now(),
        score: this.currentScore,
        sessionData
      })
    } catch (error) {
      console.error('[Monitor] 保存数据失败:', error)
    }
  },

  simulateGood() {
    this.currentScore = 92
    this.headAngle = 15
    this.neckAngle = 12
    this.backAngle = 18
    this.gradeText = '良好'
    this.showInterventionAlert('模拟数据：坐姿良好，继续保持')
