export const POSTURE_GRADES = {
  GOOD: 'good',
  FAIR: 'fair',
  POOR: 'poor'
};

export const POSTURE_THRESHOLDS = {
  HEAD_ANGLE: {
    GOOD: 30,
    FAIR: 45,
    POOR: 60
  },
  NECK_ANGLE: {
    GOOD: 20,
    FAIR: 30,
    POOR: 45
  },
  BACK_ANGLE: {
    GOOD: 25,
    FAIR: 35,
    POOR: 50
  }
};

export const INTERVENTION_CONFIG = {
  SITTING_DURATION_THRESHOLD: 30,  // 30分钟
  CUMULATIVE_POOR_THRESHOLD: 5,    // 5次
  DEVIATION_THRESHOLD: 30          // 30度
};

export const SENSOR_CONFIG = {
  SAMPLING_RATE: 10,  // 10Hz
  FILTER_WINDOW: 5    // 卡尔曼滤波窗口
};

export const STORAGE_KEYS = {
  REALTIME_DATA: 'posture_realtime',
  HISTORY_DATA: 'posture_history',
  USER_CONFIG: 'posture_config'
};

// src/common/utils/math-utils.js

export function kalmanFilter(data, windowSize = 5) {
  if (data.length < windowSize) {
    return data;
  }

  const result = [];
  for (let i = 0; i < data.length; i++) {
    const start = Math.max(0, i - Math.floor(windowSize / 2));
    const end = Math.min(data.length, i + Math.floor(windowSize / 2) + 1);
    const window = data.slice(start, end);
    const avg = window.reduce((sum, val) => sum + val, 0) / window.length;
    result.push(avg);
  }

  return result;
}

export function lowPassFilter(current, previous, alpha = 0.8) {
  return alpha * previous + (1 - alpha) * current;
}

export function calculateAngle(acceleration, gravity = 9.81) {
  const { x, y, z } = acceleration;
  const magnitude = Math.sqrt(x * x + y * y + z * z);

  if (magnitude === 0) return 0;

  const sinAngle = Math.sqrt(x * x + z * z) / magnitude;
  const angle = Math.asin(sinAngle) * (180 / Math.PI);

  return Math.round(angle * 10) / 10;
}

export function weightedAverage(values, weights) {
  if (values.length !== weights.length) {
    throw new Error('Values and weights must have same length');
  }

  let sum = 0;
  let weightSum = 0;

  for (let i = 0; i < values.length; i++) {
    sum += values[i] * weights[i];
    weightSum += weights[i];
  }

  return weightSum === 0 ? 0 : sum / weightSum;
}

export function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

export function linearInterpolation(start, end, factor) {
  return start + (end - start) * factor;
}

// src/common/lib/posture-engine.js

import { POSTURE_GRADES, POSTURE_THRESHOLDS } from '../utils/constants';
import { calculateAngle, weightedAverage, clamp } from '../utils/math-utils';

export default class PostureEngine {
  constructor() {
    this.weights = {
      head: 0.3,
      neck: 0.4,
      back: 0.3
    };

    this.history = [];
    this.maxHistorySize = 100;
  }

  /**
   * 评估姿态
   * @param {Object} sensorData - 传感器数据
   * @returns {Object} 评估结果
   */
  assess(sensorData) {
    const { acceleration, gyroscope } = sensorData;

    // 计算各部位角度
    const headAngle = this.calculateHeadAngle(acceleration);
    const neckAngle = this.calculateNeckAngle(acceleration, gyroscope);
    const backAngle = this.calculateBackAngle(acceleration);

    // 计算综合评分
    const score = this.calculateOverallScore(headAngle, neckAngle, backAngle);

    // 判定等级
    const grade = this.determineGrade(score);

    // 计算偏离度
    const deviation = this.calculateDeviation(headAngle, neckAngle, backAngle);

    const result = {
      headAngle,
      neckAngle,
      backAngle,
      score,
      grade,
      deviation,
      timestamp: Date.now()
    };

    // 记录历史
    this.addToHistory(result);

    return result;
  }

  /**
   * 计算头部角度
   */
  calculateHeadAngle(acceleration) {
    const angle = calculateAngle(acceleration);
    return clamp(angle, 0, 90);
  }

  /**
   * 计算颈部角度
   */
  calculateNeckAngle(acceleration, gyroscope) {
    const { x, y, z } = acceleration;

    // 基于加速度计的颈部角度
    const accelAngle = Math.atan2(x, Math.sqrt(y * y + z * z)) * (180 / Math.PI);

    // 基于陀螺仪的角速度积分（简化）
    const gyroAngle = gyroscope ? gyroscope.x * 0.1 : 0;

    // 融合算法
    const fusedAngle = 0.8 * accelAngle + 0.2 * gyroAngle;

    return clamp(Math.abs(fusedAngle), 0, 90);
  }

  /**
   * 计算背部角度
   */
  calculateBackAngle(acceleration) {
    const { y, z } = acceleration;
    const angle = Math.atan2(y, z) * (180 / Math.PI);

    return clamp(Math.abs(angle), 0, 90);
  }

  /**
   * 计算综合评分
   */
  calculateOverallScore(headAngle, neckAngle, backAngle) {
    // 各部位评分（0-100分）
    const headScore = this.scoreAngle(headAngle, POSTURE_THRESHOLDS.HEAD_ANGLE);
    const neckScore = this.scoreAngle(neckAngle, POSTURE_THRESHOLDS.NECK_ANGLE);
    const backScore = this.scoreAngle(backAngle, POSTURE_THRESHOLDS.BACK_ANGLE);

    // 加权平均
    const scores = [headScore, neckScore, backScore];
    const weights = [this.weights.head, this.weights.neck, this.weights.back];

    return Math.round(weightedAverage(scores, weights));
  }

  /**
   * 角度评分
   */
  scoreAngle(angle, thresholds) {
    if (angle <= thresholds.GOOD) {
      return 100;
    } else if (angle <= thresholds.FAIR) {
      // 线性插值 60-100
      const factor = (thresholds.FAIR - angle) / (thresholds.FAIR - thresholds.GOOD);
      return 60 + factor * 40;
    } else if (angle <= thresholds.POOR) {
      // 线性插值 30-60
      const factor = (thresholds.POOR - angle) / (thresholds.POOR - thresholds.FAIR);
      return 30 + factor * 30;
    } else {
      // 低于30分
      const factor = Math.max(0, 1 - (angle - thresholds.POOR) / 30);
      return factor * 30;
    }
  }

  /**
   * 判定等级
   */
  determineGrade(score) {
    if (score >= 80) return POSTURE_GRADES.GOOD;
    if (score >= 60) return POSTURE_GRADES.FAIR;
    return POSTURE_GRADES.POOR;
  }

  /**
   * 计算偏离度
   */
  calculateDeviation(headAngle, neckAngle, backAngle) {
    const headDev = Math.max(0, headAngle - POSTURE_THRESHOLDS.HEAD_ANGLE.GOOD);
    const neckDev = Math.max(0, neckAngle - POSTURE_THRESHOLDS.NECK_ANGLE.GOOD);
    const backDev = Math.max(0, backAngle - POSTURE_THRESHOLDS.BACK_ANGLE.GOOD);

    return Math.round((headDev + neckDev + backDev) / 3);
  }

  /**
   * 添加到历史记录
   */
  addToHistory(result) {
    this.history.push(result);

    if (this.history.length > this.maxHistorySize) {
      this.history.shift();
    }
  }

  /**
   * 获取历史统计
   */
  getStatistics() {
    if (this.history.length === 0) {
      return {
        averageScore: 0,
        goodRate: 0,
        poorRate: 0,
        averageDeviation: 0
      };
    }

    const scores = this.history.map(h => h.score);
    const deviations = this.history.map(h => h.deviation);
    const grades = this.history.map(h => h.grade);

    const averageScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const goodCount = grades.filter(g => g === POSTURE_GRADES.GOOD).length;
    const poorCount = grades.filter(g => g === POSTURE_GRADES.POOR).length;
    const averageDeviation = Math.round(deviations.reduce((a, b) => a + b, 0) / deviations.length);

    return {
      averageScore,
      goodRate: Math.round((goodCount / grades.length) * 100),
      poorRate: Math.round((poorCount / grades.length) * 100),
      averageDeviation
    };
  }

  /**
   * 重置历史
   */
  resetHistory() {
    this.history = [];
  }
}

// src/common/lib/intervention-system.js

import { INTERVENTION_CONFIG, POSTURE_GRADES } from '../utils/constants';

export default class InterventionSystem {
  constructor(config = {}) {
    this.config = {
      sittingDurationThreshold: config.sittingDurationThreshold || INTERVENTION_CONFIG.SITTING_DURATION_THRESHOLD,
      cumulativePoorThreshold: config.cumulativePoorThreshold || INTERVENTION_CONFIG.CUMULATIVE_POOR_THRESHOLD,
      deviationThreshold: config.deviationThreshold || INTERVENTION_CONFIG.DEVIATION_THRESHOLD,
      ...config
    };

    this.session = {
      startTime: null,
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    this.interventionHistory = [];
  }

  /**
   * 开始监测会话
   */
  startSession() {
    this.session = {
      startTime: Date.now(),
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    console.log('[Intervention] 会话开始');
  }

  /**
   * 停止监测会话
   */
  stopSession() {
    const sessionData = { ...this.session };
    this.interventionHistory.push(sessionData);

    console.log('[Intervention] 会话结束', sessionData);

    this.session = {
      startTime: null,
      sittingDuration: 0,
      cumulativePoor: 0,
      interventionCount: 0,
      lastInterventionTime: null
    };

    return sessionData;
  }

  /**
   * 更新监测数据
   * @param {Object} postureResult - 姿态评估结果
   * @returns {Object} 干预决策
   */
  update(postureResult) {
    if (!this.session.startTime) {
      return { shouldIntervene: false, reason: null };
    }

    // 更新久坐时长
    this.updateSittingDuration();

    // 更新累计不良姿态
    this.updateCumulativePoor(postureResult);

    // 检查是否需要干预
    const intervention = this.checkIntervention(postureResult);

    return intervention;
  }

  /**
   * 更新久坐时长
   */
  updateSittingDuration() {
    if (this.session.startTime) {
      this.session.sittingDuration = Math.floor((Date.now() - this.session.startTime) / 60000);
    }
  }

  /**
   * 更新累计不良姿态
   */
  updateCumulativePoor(postureResult) {
    if (postureResult.grade === POSTURE_GRADES.POOR) {
      this.session.cumulativePoor++;
    } else if (postureResult.grade === POSTURE_GRADES.GOOD) {
      // 良好姿态可以重置计数
      this.session.cumulativePoor = Math.max(0, this.session.cumulativePoor - 1);
    }
  }

  /**
   * 检查是否需要干预
   */
  checkIntervention(postureResult) {
    const reasons = [];

    // 检查久坐时间
    if (this.session.sittingDuration >= this.config.sittingDurationThreshold) {
      reasons.push('sitting_duration');
    }

    // 检查姿态偏离
    if (postureResult.deviation >= this.config.deviationThreshold) {
      reasons.push('posture_deviation');
    }

    // 检查累计不良
    if (this.session.cumulativePoor >= this.config.cumulativePoorThreshold) {
      reasons.push('cumulative_poor');
    }

    // 防止频繁干预（至少间隔5分钟）
    const now = Date.now();
    if (this.session.lastInterventionTime) {
      const timeSinceLastIntervention = now - this.session.lastInterventionTime;
      if (timeSinceLastIntervention < 5 * 60 * 1000) {
        return {
          shouldIntervene: false,
          reason: null,
          message: '距离上次提醒不足5分钟'
        };
      }
    }

    if (reasons.length > 0) {
      this.session.interventionCount++;
      this.session.lastInterventionTime = now;

      const message = this.generateMessage(reasons, postureResult);

      return {
        shouldIntervene: true,
        reason: reasons[0],
        message,
        timestamp: now
      };
    }

    return {
      shouldIntervene: false,
      reason: null
    };
  }

  /**
   * 生成干预消息
   */
  generateMessage(reasons, postureResult) {
    const messages = {
      sitting_duration: '您已经连续坐了' + this.session.sittingDuration + '分钟，建议起身活动一下',
      posture_deviation: '检测到您的坐姿偏离较大，请调整姿势',
      cumulative_poor: '您今天的不良坐姿次数较多，请注意保持正确坐姿'
    };

    const primaryReason = reasons[0];
    let message = messages[primaryReason] || '请注意保持正确坐姿';

    // 根据等级添加额外建议
    if (postureResult.grade === POSTURE_GRADES.POOR) {
      message += '。当前坐姿不佳，请立即调整。';
    } else if (postureResult.grade === POSTURE_GRADES.FAIR) {
      message += '。可以做得更好，继续保持。';
    }

    return message;
  }

  /**
   * 获取会话统计
   */
  getSessionStats() {
    return {
      sittingDuration: this.session.sittingDuration,
      cumulativePoor: this.session.cumulativePoor,
      interventionCount: this.session.interventionCount,
      isMonitoring: !!this.session.startTime
    };
  }

  /**
   * 获取历史统计
   */
  getHistoryStats() {
    if (this.interventionHistory.length === 0) {
      return {
        totalSessions: 0,
        averageInterventions: 0,
        totalInterventions: 0
      };
    }

    const totalInterventions = this.interventionHistory.reduce(
      (sum, session) => sum + session.interventionCount, 0
    );

    return {
      totalSessions: this.interventionHistory.length,
      averageInterventions: Math.round(totalInterventions / this.interventionHistory.length),
      totalInterventions
    };
  }
}

// src/common/lib/sensor-manager.js

import sensor from '@system.sensor';
import { SENSOR_CONFIG } from '../utils/constants';
import { kalmanFilter, lowPassFilter } from '../utils/math-utils';

export default class SensorManager {
  constructor() {
    this.isRunning = false;
    this.dataBuffer = {
      acceleration: [],
      gyroscope: []
    };

    this.currentData = {
      acceleration: { x: 0, y: 0, z: 0 },
      gyroscope: { x: 0, y: 0, z: 0 }
    };

    this.filteredData = {
      acceleration: { x: 0, y: 0, z: 0 },
      gyroscope: { x: 0, y: 0, z: 0 }
    };

    this.callbacks = {
      onData: null,
      onError: null
    };

    this.bufferSize = SENSOR_CONFIG.FILTER_WINDOW;
  }

  /**
   * 注册数据回调
   */
  onData(callback) {
    this.callbacks.onData = callback;
  }

  /**
   * 注册错误回调
   */
  onError(callback) {
    this.callbacks.onError = callback;
  }

  /**
   * 开始采集传感器数据
   */
  start() {
    if (this.isRunning) {
      console.warn('[Sensor] 已经在运行');
      return;
    }

    this.isRunning = true;
    this.dataBuffer = { acceleration: [], gyroscope: [] };

    // 启动加速度计
    this.startAccelerometer();

    // 启动陀螺仪
    this.startGyroscope();

    console.log('[Sensor] 开始采集');
  }

  /**
   * 停止采集
   */
  stop() {
    this.isRunning = false;

    // 停止加速度计
    this.stopAccelerometer();

    // 停止陀螺仪
    this.stopGyroscope();

    console.log('[Sensor] 停止采集');
  }

  /**
   * 启动加速度计
   */
  startAccelerometer() {
    sensor.subscribeAccelerometer({
      callback: (data) => {
        if (!this.isRunning) return;

        this.currentData.acceleration = {
          x: data.x,
          y: data.y,
          z: data.z
        };

        // 更新缓冲区
        this.dataBuffer.acceleration.push(this.currentData.acceleration);
        if (this.dataBuffer.acceleration.length > this.bufferSize) {
          this.dataBuffer.acceleration.shift();
        }

        // 应用滤波
        this.applyFilter();

        // 通知数据更新
        this.notifyDataUpdate();
      }
    });
  }

  /**
   * 停止加速度计
   */
  stopAccelerometer() {
    sensor.unsubscribeAccelerometer();
  }

  /**
   * 启动陀螺仪
   */
  startGyroscope() {
    sensor.subscribeGyroscope({
      callback: (data) => {
        if (!this.isRunning) return;

        this.currentData.gyroscope = {
          x: data.x,
          y: data.y,
          z: data.z
        };

        // 更新缓冲区
        this.dataBuffer.gyroscope.push(this.currentData.gyroscope);
        if (this.dataBuffer.gyroscope.length > this.bufferSize) {
          this.dataBuffer.gyroscope.shift();
        }
      }
    });
  }

  /**
   * 停止陀螺仪
   */
  stopGyroscope() {
    sensor.unsubscribeGyroscope();
  }

  /**
   * 应用滤波
   */
  applyFilter() {
    // 对加速度计数据应用卡尔曼滤波
    if (this.dataBuffer.acceleration.length >= this.bufferSize) {
      const xValues = this.dataBuffer.acceleration.map(d => d.x);
      const yValues = this.dataBuffer.acceleration.map(d => d.y);
      const zValues = this.dataBuffer.acceleration.map(d => d.z);

      const filteredX = kalmanFilter(xValues, this.bufferSize);
      const filteredY = kalmanFilter(yValues, this.bufferSize);
      const filteredZ = kalmanFilter(zValues, this.bufferSize);

      const lastIdx = filteredX.length - 1;

      this.filteredData.acceleration = {
        x: filteredX[lastIdx],
        y: filteredY[lastIdx],
        z: filteredZ[lastIdx]
      };
    } else {
      // 数据不足，使用当前值
      this.filteredData.acceleration = { ...this.currentData.acceleration };
    }

    // 陀螺仪数据使用低通滤波
    if (this.filteredData.gyroscope.x === 0) {
      this.filteredData.gyroscope = { ...this.currentData.gyroscope };
    } else {
      this.filteredData.gyroscope = {
        x: lowPassFilter(this.currentData.gyroscope.x, this.filteredData.gyroscope.x),
        y: lowPassFilter(this.currentData.gyroscope.y, this.filteredData.gyroscope.y),
        z: lowPassFilter(this.currentData.gyroscope.z, this.filteredData.gyroscope.z)
      };
    }
  }

  /**
   * 通知数据更新
   */
  notifyDataUpdate() {
    if (this.callbacks.onData) {
      this.callbacks.onData({
        acceleration: this.filteredData.acceleration,
        gyroscope: this.filteredData.gyroscope,
        raw: this.currentData
      });
    }
  }

  /**
   * 获取当前数据
   */
  getCurrentData() {
    return {
      acceleration: this.filteredData.acceleration,
      gyroscope: this.filteredData.gyroscope
    };
  }
}

// src/common/lib/storage-manager.js

import storage from '@system.storage';
import { STORAGE_KEYS } from '../utils/constants';

export default class StorageManager {
  constructor() {
    this.cache = {};
    this.isLoaded = false;
  }

  /**
   * 初始化存储
   */
  async init() {
    try {
      // 加载用户配置
      const config = await this.get(STORAGE_KEYS.USER_CONFIG);
      if (!config) {
        await this.set(STORAGE_KEYS.USER_CONFIG, this.getDefaultConfig());
      }

      this.isLoaded = true;
      console.log('[Storage] 初始化完成');
    } catch (error) {
      console.error('[Storage] 初始化失败:', error);
    }
  }

  /**
   * 获取默认配置
   */
  getDefaultConfig() {
    return {
      alertEnabled: true,
      alertInterval: 30,
      sensitivity: 'medium',
      restDuration: 5,
      dailyGoal: 80,
      workingHours: {
        start: '09:00',
        end: '18:00'
      }
    };
  }

  /**
   * 存储数据
   */
  set(key, value) {
    return new Promise((resolve, reject) => {
      try {
        const data = JSON.stringify(value);
        storage.set({
          key,
          value: data,
          success: () => {
            this.cache[key] = value;
            resolve();
          },
          fail: (error) => {
            reject(error);
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * 获取数据
   */
  get(key) {
    return new Promise((resolve, reject) => {
      // 先检查缓存
      if (this.cache[key] !== undefined) {
        resolve(this.cache[key]);
        return;
      }

      try {
        storage.get({
          key,
          success: (data) => {
            try {
              const value = JSON.parse(data);
              this.cache[key] = value;
              resolve(value);
            } catch (parseError) {
              resolve(data);
            }
          },
          fail: (error) => {
            reject(error);
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * 删除数据
   */
  delete(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key,
        success: () => {
          delete this.cache[key];
          resolve();
        },
        fail: (error) => {
          reject(error);
        }
      });
    });
  }

  /**
   * 存储实时数据
   */
  async saveRealtimeData(data) {
    await this.set(STORAGE_KEYS.REALTIME_DATA, data);
  }

  /**
   * 获取实时数据
   */
  async getRealtimeData() {
    return await this.get(STORAGE_KEYS.REALTIME_DATA);
  }

  /**
   * 保存历史记录
   */
  async saveHistoryRecord(record) {
    const history = await this.get(STORAGE_KEYS.HISTORY_DATA) || [];
    history.push(record);

    // 只保留最近30天的数据
    const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
    const filteredHistory = history.filter(h => h.timestamp > thirtyDaysAgo);

    await this.set(STORAGE_KEYS.HISTORY_DATA, filteredHistory);
  }

  /**
   * 获取历史记录
   */
  async getHistoryRecord() {
    return await this.get(STORAGE_KEYS.HISTORY_DATA) || [];
  }

  /**
   * 保存用户配置
   */
  async saveConfig(config) {
    await this.set(STORAGE_KEYS.USER_CONFIG, config);
  }

  /**
   * 获取用户配置
   */
  async getConfig() {
    return await this.get(STORAGE_KEYS.USER_CONFIG);
  }

  /**
   * 清除历史数据
   */
  async clearHistory() {
    await this.delete(STORAGE_KEYS.HISTORY_DATA);
  }

  /**
   * 清除所有数据
   */
  async clearAll() {
    await this.delete(STORAGE_KEYS.REALTIME_DATA);
    await this.delete(STORAGE_KEYS.HISTORY_DATA);
    await this.delete(STORAGE_KEYS.USER_CONFIG);
    this.cache = {};
  }
}

// src/common/lib/data-analytics.js

import StorageManager from './storage-manager';
import { POSTURE_GRADES } from '../utils/constants';

export default class DataAnalytics {
  constructor() {
    this.storageManager = new StorageManager();
  }

  /**
   * 初始化分析模块
   */
  async init() {
    await this.storageManager.init();
  }

  /**
   * 获取每日统计
   */
  async getDailyStats(date = new Date()) {
    const history = await this.storageManager.getHistoryRecord();
    const dayStart = new Date(date);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(date);
    dayEnd.setHours(23, 59, 59, 999);

    const dailyRecords = history.filter(record => {
      const recordTime = record.timestamp;
      return recordTime >= dayStart.getTime() && recordTime <= dayEnd.getTime();
    });

    if (dailyRecords.length === 0) {
      return {
        averageScore: 0,
        goodRate: 0,
        fairRate: 0,
        poorRate: 0,
        totalSessions: 0,
        averageSessionDuration: 0,
        totalInterventions: 0
      };
    }

    const scores = dailyRecords.map(r => r.score);
    const grades = dailyRecords.map(r => r.grade);

    const averageScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const goodCount = grades.filter(g => g === POSTURE_GRADES.GOOD).length;
    const fairCount = grades.filter(g => g === POSTURE_GRADES.FAIR).length;
    const poorCount = grades.filter(g => g === POSTURE_GRADES.POOR).length;

    const totalSessions = dailyRecords.length;
    const averageSessionDuration = Math.round(
      dailyRecords.reduce((sum, r) => sum + (r.sessionData?.sittingDuration || 0), 0) / totalSessions
    );
    const totalInterventions = dailyRecords.reduce(
      (sum, r) => sum + (r.sessionData?.interventionCount || 0), 0
    );

    return {
      averageScore,
      goodRate: Math.round((goodCount / totalSessions) * 100),
      fairRate: Math.round((fairCount / totalSessions) * 100),
      poorRate: Math.round((poorCount / totalSessions) * 100),
      totalSessions,
      averageSessionDuration,
      totalInterventions
    };
  }

  /**
   * 获取每周统计
   */
  async getWeeklyStats() {
    const history = await this.storageManager.getHistoryRecord();
    const weeklyData = [];

    // 获取最近7天的数据
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dayStats = await this.getDailyStats(date);
      weeklyData.push({
        date: date.toISOString().split('T')[0],
        ...dayStats
      });
    }

    return weeklyData;
  }

  /**
   * 获取趋势数据
   */
  async getTrendData(days = 30) {
    const history = await this.storageManager.getHistoryRecord();
    const trendData = [];

    // 获取最近N天的数据
    for (let i = days - 1; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dayStats = await this.getDailyStats(date);
      trendData.push({
        date: date.toISOString().split('T')[0],
        score: dayStats.averageScore,
        goodRate: dayStats.goodRate
      });
    }

    return trendData;
  }

  /**
   * 生成健康报告
   */
  async generateHealthReport() {
    const dailyStats = await this.getDailyStats();
    const weeklyStats = await this.getWeeklyStats();
    const trendData = await this.getTrendData(7);

    // 计算改善率
    const improvementRate = this.calculateImprovementRate(trendData);

    // 生成建议
    const suggestions = this.generateSuggestions(dailyStats, weeklyStats);

    return {
      summary: {
        averageScore: dailyStats.averageScore,
        goodRate: dailyStats.goodRate,
        totalSessions: dailyStats.totalSessions,
        improvementRate
      },
      weeklyTrend: weeklyStats,
      suggestions,
      generatedAt: Date.now()
    };
  }

  /**
   * 计算改善率
   */
  calculateImprovementRate(trendData) {
    if (trendData.length < 2) return 0;

    const recentScores = trendData.slice(-3).map(d => d.score);
    const olderScores = trendData.slice(0, 3).map(d => d.score);

    const recentAvg = recentScores.reduce((a, b) => a + b, 0) / recentScores.length;
    const olderAvg = olderScores.reduce((a, b) => a + b, 0) / olderScores.length;

    if (olderAvg === 0) return 0;

    return Math.round(((recentAvg - olderAvg) / olderAvg) * 100);
  }

  /**
   * 生成建议
   */
  generateSuggestions(dailyStats, weeklyStats) {
    const suggestions = [];

    // 基于每日统计的建议
    if (dailyStats.goodRate < 60) {
      suggestions.push({
        type: 'posture',
        priority: 'high',
        message: '您的坐姿良好率较低，建议增加休息频率，每30分钟起身活动'
      });
    }

    if (dailyStats.totalInterventions > 10) {
      suggestions.push({
        type: 'frequency',
        priority: 'medium',
        message: '您今天收到了较多提醒，建议调整坐姿习惯，减少不良姿态'
      });
    }

    if (dailyStats.averageSessionDuration > 60) {
      suggestions.push({
        type: 'duration',
        priority: 'high',
        message: '您的连续坐姿时间较长，建议每小时起身活动5-10分钟'
      });
    }

    // 基于周统计的建议
    const weeklyAverageScore = weeklyStats.reduce((sum, day) => sum + day.averageScore, 0) / weeklyStats.length;
    if (weeklyAverageScore < 70) {
      suggestions.push({
        type: 'overall',
        priority: 'high',
        message: '本周整体坐姿评分较低，建议使用腰靠、调整桌椅高度来改善坐姿'
      });
    }

    // 如果没有特别问题，给予鼓励
    if (suggestions.length === 0) {
      suggestions.push({
        type: 'positive',
        priority: 'low',
        message: '您的坐姿表现良好，继续保持！建议适当进行颈部和背部伸展运动'
      });
    }

    return suggestions;
  }

  /**
   * 导出数据
   */
  async exportData() {
    const history = await this.storageManager.getHistoryRecord();
    const config = await this.storageManager.getConfig();

    return {
      exportTime: Date.now(),
      config,
      history,
      statistics: await this.getDailyStats()
    };
  }

  /**
   * 清除数据
   */
  async clearData() {
    await this.storageManager.clearHistory();
  }
}

